sys_script_include.script:
var BR = Class.create();
BR.prototype = {
    initialize: function() {
    },
	setStatusToScheduled: function(){
	if (current.u_status) {
        current.u_status = 'Scheduled';
        gs.addInfoMessage("Status is set to 'Scheduled'.");
    }
	},

	sendNotificationWhenScheduled: function(){
			if (current.u_status == 'scheduled'){
		gs.addInfoMessage("Appointment is Scheduled");
	}
	},

	changeStatusToComplete: function(){
		if (current.work_notes.contains('finished')){
		current.u_status = 'completed';
		gs.addInfoMessage("Appointment is Finished");
	}
	},

	setPriorityToHigh: function(){
		if (current.u_vip == true){
		current.u_priority = "high";
		gs.addInfoMessage("VIP in the house")
	}
	},

	calTotal: function(){

    	if (current.u_dosage && current.u_frequency){
        var freq = null;
        if (current.u_frequency == 'once_daily'){
            freq = 1;
        }
        if (current.u_frequency == 'twice_daily'){
            freq = 2;
        }
        if (current.u_frequency == 'thrice_daily'){
            freq = 3;
        }  
        if(current.u_frequency == 'once_week'){
                freq = 1/7;
        }
        var days = gs.dateDiff(current.u_start_date,current.u_end_date,true);
        var dosage = current.u_dosage;

        var ans = freq * dosage * (days/(3600*24));
        current.u_total_dosage = ans;
        gs.addInfoMessage("Total Dosage is "+ ans);

    }
	},

	updateLabTest: function(){

		if(current.u_results != previous.u_results){
		gs.addInfoMessage("Result updated..")
	}
	},

	updateOccupancyInWard: function(){

		var ward = new GlideRecord('u_ward_table');
		var wardID = current.u_ward_id;
		ward.addQuery('sys_id', wardID);
		ward.query();
		if(ward.next()){
			if (ward.u_capacity > ward.u_occupancy){
            ward.u_occupancy = ward.u_occupancy + 1;
			gs.addInfoMessage('occupancy updated in ward table to '+ ward.u_occupancy);
			}
			else{
				ward.setAbortAction(true);
				gs.addInfoMessage("No beds Available");
			}
			ward.update();
		}
	},

	updateOccupiedBeds: function(){
		if (current.u_assigned_to && previous.u_assigned_to != current.u_assigned_to){
		if (current.u_occupied_beds<current.u_bed_count){
			current.u_occupied_beds += 1;
			gs.addInfoMessage("Occupied Beds Updated");
		}
		else{
			gs.addErrorMessage("No beds available in this room!");
			current.setAbortAction(true);
			}
		}
	},

	notifyBilling: function(){
		if (current.u_status == 'completed'){
		gs.addInfoMessage("Appointment is Completed");
	}

	},

	updateCoverageDetails: function(){
		if (current.u_policy_number != previous.u_policy_number){
		var description = current.u_policy_number.u_description;
		current.u_coverage_details = description;
		gs.addInfoMessage("Coverage Details are updated.");
	}
	},
    type: 'BR'
};
